}

package main

import "fmt"

type User struct {
	Username string
	Email    string
}

func (u User) Greet() string {
	return fmt.Sprintf("Welcome, %s (%s)!", u.Username, u.Email)
}

func main() {
	user := User{Username: "Alice", Email: "alice@example.com"}
	fmt.Println(user.Greet())
}

package main

import "fmt"

type Notifier interface {
	Notify() string
}

type EmailAlert struct {
	Subject string
}

func (e EmailAlert) Notify() string {
	return "[Email] " + e.Subject
}

func SendNotification(n Notifier) {
	fmt.Println(n.Notify())
}

func main() {
	SendNotification(EmailAlert{Subject: "Welcome to Interfaces!"})
}

package main

import (
	"fmt"
	"time"
)

func worker(id int, ch chan string) {
	time.Sleep(100 * time.Millisecond)
	ch <- fmt.Sprintf("worker %d completed work", id)
}

func main() {
	ch := make(chan string, 3)
	for i := 1; i <= 3; i++ {
		go worker(i, ch)
	}

	for i := 1; i <= 3; i++ {
		fmt.Println(<-ch)
	}
}
